add_action('init', function() {
    $x = array('public' => true, 'exclude_from_search' => false, 'show_in_admin_all_list' => true, 'show_in_admin_status_list' => true);
    register_post_status('wc-fake-order', array_merge($x, array('label' => 'Fake Order')));
    register_post_status('wc-returned-order', array_merge($x, array('label' => 'Returned Order')));
    register_post_status('wc-offline-purchase', array_merge($x, array('label' => 'Purchase Manual')));
});

add_filter('wc_order_statuses', function($s) {
    if (isset($s['wc-processing'])) { $s['wc-fake-order'] = 'Fake Order'; $s['wc-returned-order'] = 'Returned Order'; $s['wc-offline-purchase'] = 'Purchase Manual'; } return $s;
});

